using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Text.Json;
using YeManInputHost.Diagnostics;
using static YeManInputHost.Diagnostics.HostClassicMotorProtocol;
internal static class SteamProtocolTests
{
 static readonly List<object> cases=new();static int checks;
 static void Need(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static void Case(string name,Action action){int before=checks;try{action();cases.Add(new{name,passed=true,checks=checks-before});}catch(Exception e){cases.Add(new{name,passed=false,checks=checks-before,error=e.Message});}}
 // Construct a full packed Valve feature command from primary-source structure fields.
 // This fixture has an application placeholder byte; the actual USBIP split below
 // removes it before taking command into ReportId, exactly as the pinned SDK does.
 static byte[] Packet(ushort left,ushort right,byte length=0,byte type=0,ushort intensity=0,sbyte leftGain=2,sbyte rightGain=0){var full=new byte[65];full[1]=0xEB;full[2]=length;full[3]=type;BinaryPrimitives.WriteUInt16LittleEndian(full.AsSpan(4),intensity);BinaryPrimitives.WriteUInt16LittleEndian(full.AsSpan(6),left);BinaryPrimitives.WriteUInt16LittleEndian(full.AsSpan(8),right);full[10]=unchecked((byte)leftGain);full[11]=unchecked((byte)rightGain);return full;}
 static Motors DecodeFull(byte[] full){var value=Decode(Profile.SteamDeckClassicRumble,1,full[1],full.AsSpan(2),out var m);Need(value==Result.Motors,"full packed command must decode");return m;}
 static JsonElement Read(string value)=>JsonDocument.Parse(value).RootElement.Clone();
 static void Observe(HostGameOutputObservation mailbox,HostGameOutputObservation.Binding binding,object controller,ushort left,ushort right){var p=Packet(left,right);mailbox.Observe(binding,controller,1,p[1],p.AsMemory(2),0x1234);}
 static int Main(){
  Case("exact-profile-binding-d12-three-targets-and-alias-refusal",()=>{Need(Bind("steam-deck-composite")==Profile.SteamDeckClassicRumble,"Steam exact binding");Need(Bind("dualsense-edge")==Profile.DualSenseEdgeUsb,"Sony retained");Need(Bind("xbox-elite-v2")==Profile.XboxEliteXInputClassic&&global::YeManCC.Capabilities.HcControllerGameFeedbackCapabilityCatalog.ResolveToken("xbox-elite-v2")==3,"Xbox exact target token3");foreach(var x in new[]{"steamdeck","steam-deck","STEAM-DECK-COMPOSITE",""})Need(Bind(x)==Profile.Unsupported,"no alias authority:"+x);});
 Case("independent-u16-motors-use-frozen-high-byte",()=>{var m=DecodeFull(Packet(0x1234,0xA5FE));Need(m.Left==0x12&&m.Right==0xA5&&m.Compatibility==3&&!m.IsStop,"independent high bytes");});
 Case("explicit-zero-and-low-only-stop-match-frozen-normalization",()=>{Need(DecodeFull(Packet(0,0)).IsStop,"zero stop");Need(DecodeFull(Packet(0xFF,0xFF)).IsStop,"frozen floor normalization");Need(DecodeFull(Packet(0xFFFF,0xFFFF)).Left==255,"full scale");});
 Case("sdl-zero-length-and-declared-packed-length-both-admitted",()=>{Need(DecodeFull(Packet(0x1200,0xA500,0)).Left==0x12,"SDL length0");Need(DecodeFull(Packet(0x1200,0xA500,9)).Right==0xA5,"payload length9");});
 Case("wrong-api-or-command-not-a-motor-update",()=>{var p=Packet(0x1200,0xA500);foreach(byte src in new byte[]{0,2,3,255})Need(Decode(Profile.SteamDeckClassicRumble,src,0xEB,p.AsSpan(2),out _)==Result.NotApplicable,"source refused");foreach(byte id in new byte[]{0,2,0xEA,0x8F,0x87})Need(Decode(Profile.SteamDeckClassicRumble,1,id,p.AsSpan(2),out _)==Result.NotApplicable,"haptic/pulse/config separate");});
 Case("truncated-and-oversized-packets-cannot-decode",()=>{foreach(int n in new[]{0,1,8,9,10,62,64,65,256})Need(Decode(Profile.SteamDeckClassicRumble,1,0xEB,new byte[n],out _)==Result.Malformed,"exact63:"+n);});
 Case("unknown-length-or-rumble-type-cannot-write",()=>{foreach(byte length in new byte[]{1,8,10,255})Need(Decode(Profile.SteamDeckClassicRumble,1,0xEB,Packet(0,0,length).AsSpan(2),out _)==Result.Malformed,"length");foreach(byte type in new byte[]{1,2,255})Need(Decode(Profile.SteamDeckClassicRumble,1,0xEB,Packet(0,0,0,type).AsSpan(2),out _)==Result.UnsupportedHapticMode,"type");});
 Case("intensity-and-gain-are-not-motor-amplitudes",()=>{var a=DecodeFull(Packet(0x1200,0xA500));var b=DecodeFull(Packet(0x1200,0xA500,0,0,0xFFFF,-128,127));Need(a==b,"frozen adaptation ignores gain/intensity");});
 Case("sony-motors-and-compatibility-unchanged",()=>{var p=new byte[63];p[0]=3;p[2]=0xA5;p[3]=0x12;Need(Decode(Profile.DualSenseEdgeUsb,0,2,p,out var m)==Result.Motors&&m.Left==0x12&&m.Right==0xA5&&m.Compatibility==1,"Sony left/right");p[0]=2;p[38]=4;Need(Decode(Profile.DualSenseEdgeUsb,0,2,p,out m)==Result.Motors&&m.Compatibility==2,"Sony compat2");Need(Decode(Profile.DualSenseEdgeUsb,1,0xEB,Packet(0,0).AsSpan(2),out _)==Result.NotApplicable,"Sony cannot borrow Steam");});
 Case("real-mailbox-emits-distinct-protocol-binding",()=>{var box=new HostGameOutputObservation();var owner=new object();box.Bind(owner,"steam-deck-composite");var reply=Read(box.TryAppendBinding("{}",owner,32768));Need(reply.GetProperty("gameFeedbackProtocol").GetInt32()==2&&reply.GetProperty("gameFeedbackBindingGeneration").GetUInt64()>0,"protocol2 binding");});
 Case("real-mailbox-raw-only-drain-preserves-motor-stop",()=>{var box=new HostGameOutputObservation();var owner=new object();var binding=box.Bind(owner,"steam-deck-composite");Observe(box,binding,owner,0x1200,0xA500);Observe(box,binding,owner,0,0);box.Observe(binding,owner,3,0x83,ReadOnlyMemory<byte>.Empty,0x1235);var raw=Read(box.TryAppend("{}",owner,32768,false));Need(!raw.TryGetProperty("gameFeedbackLeft",out _),"stats cannot drain motor");Need(box.HasPending,"stop preserved");var receipt=Read(box.TryAppend("{}",owner,32768,true));Need(receipt.GetProperty("gameFeedbackLeft").GetInt32()==0&&receipt.GetProperty("gameFeedbackRight").GetInt32()==0,"stop delivered");Need(receipt.GetProperty("gameFeedbackCompatibility").GetInt32()==3&&receipt.GetProperty("gameFeedbackRevision").GetUInt64()==2,"distinct protocol revision");Need(!box.HasPending,"delivered once");});
 Case("real-mailbox-failed-capacity-append-retains-pending",()=>{var box=new HostGameOutputObservation();var owner=new object();var binding=box.Bind(owner,"steam-deck-composite");Observe(box,binding,owner,0x1200,0xA500);Need(box.TryAppend("{}",owner,2,true)=="{}"&&box.HasPending,"bounded append cannot lose motors");Need(Read(box.TryAppend("{}",owner,32768,true)).GetProperty("gameFeedbackRight").GetInt32()==0xA5,"retry preserves right");});
 Case("real-mailbox-revocation-rebind-and-wrong-sender-refuse",()=>{var box=new HostGameOutputObservation();var owner=new object();var old=box.Bind(owner,"steam-deck-composite");Observe(box,old,new object(),0x1200,0xA500);Need(!box.HasPending,"wrong sender");box.Revoke();Observe(box,old,owner,0x1200,0xA500);Need(!box.HasPending,"revoked callback");var next=box.Bind(owner,"dualsense-edge");Observe(box,old,owner,0x1200,0xA500);Need(!box.HasPending,"old generation");Observe(box,next,owner,0x1200,0xA500);var raw=Read(box.TryAppend("{}",owner,32768,true));Need(!raw.TryGetProperty("gameFeedbackLeft",out _),"Steam source cannot create Sony motors");});
 Case("independent-packed-values-1024",()=>{for(int n=0;n<1024;n++){ushort left=unchecked((ushort)(n*613+197)),right=unchecked((ushort)(n*997+59));var m=DecodeFull(Packet(left,right));Need(m.Left==left/256&&m.Right==right/256,"reference U16 floor");}});
 bool pass=cases.TrueForAll(x=>JsonSerializer.SerializeToElement(x).GetProperty("passed").GetBoolean());Console.WriteLine(JsonSerializer.Serialize(new{status=pass?"PASS":"FAIL",cases,caseCount=cases.Count,checks,actualHostMailbox=true,actualGeneratedCatalog=true,hostSessionOrPipeExecuted=false,physicalAcceptance=false,hardwareIo=false,goalComplete=false}));return pass?0:1;
 }
}
